-- Disposable PostgreSQL integration fixture. Never run on Supabase production.
-- Mimics only live fields/constraints used by the two WhatsApp migrations.
CREATE ROLE anon NOLOGIN;
CREATE ROLE authenticated NOLOGIN;
CREATE ROLE service_role NOLOGIN;
CREATE SCHEMA auth;
CREATE SCHEMA private;
GRANT USAGE ON SCHEMA public,auth,private TO service_role;
CREATE TABLE auth.users(
 id uuid PRIMARY KEY,
 email text NOT NULL,
 raw_user_meta_data jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE OR REPLACE FUNCTION auth.uid()
RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT null::uuid $$;
CREATE TABLE public.profiles(
 id uuid PRIMARY KEY REFERENCES auth.users(id),
 phone text,phone_verified_at timestamptz,
 phone_verification_method text,updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.phone_otp_challenges(
 id uuid PRIMARY KEY,
 email text NOT NULL,
 phone_e164 text NOT NULL,
 audience text NOT NULL CHECK(audience IN ('customer','retailer','seller')),
 verified_at timestamptz,consumed_at timestamptz
);
CREATE TABLE public.orders(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 user_id uuid REFERENCES auth.users(id),
 customer_phone text,customer_name text,display_order_id text,
 payment_method text,status text,
 payment_verified_at timestamptz,
 fulfillment_status text,fulfillment_updated_at timestamptz DEFAULT now(),
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.order_shipments(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 order_id bigint REFERENCES public.orders(id),
 direction text,awb_code text
);
CREATE TABLE public.whatsapp_contact_consents(
 id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
 phone_e164 text NOT NULL,
 purpose text NOT NULL CHECK(purpose IN ('transactional','marketing')),
 status text NOT NULL CHECK(status IN ('opted_in','opted_out')),
 source text NOT NULL,proof_reference text NOT NULL,
 consented_at timestamptz,revoked_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now(),
 last_event_at timestamptz,last_event_id text,
 CONSTRAINT whatsapp_contact_consents_phone_purpose_unique UNIQUE(phone_e164,purpose),
 CONSTRAINT whatsapp_contact_consents_state_check
 CHECK ((status='opted_in' AND consented_at IS NOT NULL AND revoked_at IS NULL)
 OR (status='opted_out' AND revoked_at IS NOT NULL))
);
CREATE TABLE public.whatsapp_order_consents(
 order_id bigint PRIMARY KEY REFERENCES public.orders(id),
 user_id uuid NOT NULL REFERENCES auth.users(id),
 phone_e164 text NOT NULL,
 source text NOT NULL,
 consented_at timestamptz NOT NULL,
 revoked_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now(),
 CONSTRAINT whatsapp_order_consents_source_check CHECK(source='checkout_checkbox')
);
CREATE TABLE public.whatsapp_order_notification_outbox(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 order_id bigint NOT NULL REFERENCES public.orders(id),
 event_type text NOT NULL,
 status text NOT NULL DEFAULT 'pending_review'
 CHECK(status IN ('pending_review','ready','blocked','sending','accepted','delivered','failed')),
 attempt_count int NOT NULL DEFAULT 0,
 template_name text,
 provider_message_id text,
 last_error_code text,
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now(),
 provider_sent_at timestamptz,
 provider_delivered_at timestamptz,
 provider_read_at timestamptz,
 provider_failed_at timestamptz,
 last_provider_status text,
 UNIQUE(order_id,event_type)
);

CREATE TABLE public.whatsapp_delivery_status_events(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 provider_message_id text NOT NULL,
 meta_status text NOT NULL CHECK(meta_status IN ('sent','delivered','read','failed')),
 event_at timestamptz NOT NULL,
 error_code text,
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(provider_message_id,meta_status,event_at)
);

-- Existing production triggers simulated, never deployed to live DB here.
CREATE OR REPLACE FUNCTION public.enqueue_whatsapp_event_on_consent()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.revoked_at IS NULL THEN
   PERFORM public.stage_whatsapp_order_event(NEW.order_id,'order_confirmed');
 END IF;
 RETURN NEW;
END;
$$;
CREATE TRIGGER trg_stage_whatsapp_order_on_consent
AFTER INSERT OR UPDATE OF consented_at,revoked_at
ON public.whatsapp_order_consents FOR EACH ROW
EXECUTE FUNCTION public.enqueue_whatsapp_event_on_consent();
CREATE OR REPLACE FUNCTION public.enqueue_whatsapp_event_on_order_change()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.status IS DISTINCT FROM NEW.status OR
   OLD.payment_verified_at IS DISTINCT FROM NEW.payment_verified_at THEN
   PERFORM public.stage_whatsapp_order_event(NEW.id,'order_confirmed');
 END IF;
 RETURN NEW;
END;
$$;
CREATE TRIGGER trg_stage_whatsapp_order_on_change
AFTER UPDATE OF status,payment_verified_at,fulfillment_status
ON public.orders FOR EACH ROW
EXECUTE FUNCTION public.enqueue_whatsapp_event_on_order_change();
